const fs=require('fs');
const path=require('path');
const root=path.resolve(__dirname,'../..');
const read=p=>fs.readFileSync(path.join(root,p),'utf8');
const list=read('web-v2/app/english/revision/ai-intelligence/daily-analysis/questions/page.tsx');
const review=read('web-v2/app/english/revision/ai-intelligence/daily-analysis/review/page.tsx');
const helper=read('web-v2/lib/daily-analysis.ts');
const css=read('web-v2/app/daily-analysis.css');
const need=(text,needle,label)=>{if(!text.includes(needle))throw new Error(`${label}: missing ${needle}`)};
need(helper,'dailyAnalysisNavigationKey','filtered navigation key');
need(list,'sessionStorage.setItem','category list stores its visible order');
need(list,'dailyAnalysisNavigationKey(category,range)','category and range own the navigation order');
need(review,'← Previous','Previous review control');
need(review,'Next →','Next review control');
need(review,'english_get_daily_analysis_questions_filtered','direct-open navigation fallback');
need(review,'dailyAnalysisNavigationKey(category,categoryRange)','review restores the same category and range');
need(review,'window.history.replaceState','question stepping preserves clean browser back behavior');
need(review,'setQuestionId(nextQuestionId)','Previous/Next changes the displayed question');
need(css,'.daily-review-nav','review navigation styling');
if(/english_submit_answer|english_mark_|english_set_|english_save_context_note|english_record_guess/.test(review))throw new Error('Daily Analysis review must remain read-only');
console.log('Daily Analysis filtered Previous/Next + read-only contract: OK');
